"""Register only actually inspected primary passages; do not download/inspect by implication."""
import hashlib,json,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[4];HERE=pathlib.Path(__file__).resolve().parent
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 rows=json.loads((HERE/'resources.json').read_text(encoding='utf8'))['resources'];rows=[r for r in rows if r['id'] in ['R-EP-LAN11','R-EP-RM21']]
 specs=[('R-EP-BOARD8','Nucleo-144 MB1137 historical Ethernet route','UM1974 Rev8 August2020',2020,'https://www.stmcu.jp/wp/wp-content/uploads/2017/08/UM1974_Rev8.pdf',['Section6.11/Table11 printed28–29: Ethernet route, reference source and bridge/jumper assignments'],'build/ethernet-followthrough-sources/board8.pdf','Cached PDF text plus rendered printed28 table inspected'),('R-EP-BOARD11','Nucleo-144 MB1137 current Ethernet route comparison','UM1974 Rev11 August2025',2025,'https://www.st.com/resource/en/user_manual/um1974-stm32-nucleo144-boards-mb1137-stmicroelectronics.pdf',['Section7.11/Table11 printed29–30: Ethernet route, reference source and bridge/jumper assignments'],None,'Actual primary web PDF extracted passages; direct local download did not complete and was stopped, no local capture digest claimed'),('R-EP-ERRATA24','F429/439 selected Ethernet limitations','ES0206 Rev24 July2026',2026,'https://www.st.com/resource/en/errata_sheet/es0206-stm32f427437-and-stm32f429439-device-errata-stmicroelectronics.pdf',['Sections2.16.3–2.16.6 printed34–37: Tx flush, FIFO corruption and successive-write limits','Sections2.16.8–2.16.12 printed38–39: counter rollover, status/checksum limits, giant frames and unavailable automatic pause'],None,'Actual primary web PDF extracted passages; selected clauses only')]
 for ident,title,edition,year,url,locators,capture,method in specs:
  inspection=dict(date='2026-10-18',method=method,scope=locators,limits='Selected passages only; no physical board/silicon identity, entire-document inspection or independent review claim')
  if capture:inspection['capture']=dict(path=capture,sha256=sha(ROOT/capture))
  rows.append(dict(id=ident,title=title,edition=edition,year=year,url=url,authors=['STMicroelectronics'],kind='manual',access='Named primary passages inspected',domains=['T39'],role='primary',reason='Keep board/PHY/MMIO and DMA ownership authorities separate',prerequisites=['T27 clock/pin and ownership evidence'],locators=locators,assignable=True,inspection=inspection))
 (HERE/'resources.json').write_text(json.dumps(dict(resources=rows),indent=2)+'\n',encoding='utf8')
 paths=[HERE/'resources.json',HERE/'audit.md',pathlib.Path(__file__)];gate=dict(schema_version=1,status='passage-inspected',scope='PR-T39-04 author implementation and source comparison, not external acceptance',resource_ids=[r['id'] for r in rows],research_input_sha256={p.relative_to(ROOT).as_posix():sha(p) for p in paths},limitations=['Published ISO C17/C23 exact text remains outside this selected source inspection.','Actual board revision, fitted PHY, electrical timing and normal-ring DMA behavior are separate required observations.'])
 (HERE/'research_gate.json').write_text(json.dumps(gate,indent=2)+'\n',encoding='utf8')
if __name__=='__main__':main()
